import '../models/collection.dart';
import '../models/resource.dart';

/// Represents a proposed change generated by the AI requiring user approval
class AiActionProposal {
  final String id;
  final String description;
  final String actionType; // 'reassign_collection', 'add_tags', 'delete'
  final List<String> targetResourceIds;
  final Map<String, dynamic> parameters;
  bool isExecuted;

  AiActionProposal({
    required this.id,
    required this.description,
    required this.actionType,
    required this.targetResourceIds,
    required this.parameters,
    this.isExecuted = false,
  });
}

/// Normalized Assistant Response
class AiAssistantResponse {
  final String message;
  final List<ResourceModel> matchingResources;
  final AiActionProposal? proposal;

  const AiAssistantResponse({
    required this.message,
    this.matchingResources = const [],
    this.proposal,
  });
}

/// Controlled Tool Registry for AI (§11 of Master Prompt)
/// The AI never executes raw SQL; it only accesses validated methods on authorized data.
class AiToolRegistry {
  final List<ResourceModel> Function() getResources;
  final List<CollectionModel> Function() getCollections;
  final Future<void> Function(String resourceId, String collectionId) linkResourceToCollection;
  final Future<void> Function(String resourceId) deleteResource;

  AiToolRegistry({
    required this.getResources,
    required this.getCollections,
    required this.linkResourceToCollection,
    required this.deleteResource,
  });

  /// Tool 1: search_resources
  List<ResourceModel> searchResources(String query) {
    final q = query.toLowerCase();
    return getResources().where((r) {
      return r.title.toLowerCase().contains(q) ||
          r.description.toLowerCase().contains(q) ||
          r.url.toLowerCase().contains(q) ||
          r.notes.toLowerCase().contains(q) ||
          (r.locationName != null && r.locationName!.toLowerCase().contains(q)) ||
          r.tags.any((t) => t.toLowerCase().contains(q));
    }).toList();
  }

  /// Tool 2: suggest_category & organize
  AiActionProposal? prepareBulkOrganization({
    required String targetCategory,
    required List<String> resourceIds,
  }) {
    final collections = getCollections();
    final match = collections.firstWhere(
      (c) => c.name.toLowerCase().contains(targetCategory.toLowerCase()),
      orElse: () => collections.first,
    );

    return AiActionProposal(
      id: DateTime.now().millisecondsSinceEpoch.toString(),
      description: 'Move ${resourceIds.length} items to "${match.name}"',
      actionType: 'reassign_collection',
      targetResourceIds: resourceIds,
      parameters: {'targetCollectionId': match.id, 'collectionName': match.name},
    );
  }

  /// Execute a confirmed proposal
  Future<void> executeProposal(AiActionProposal proposal) async {
    if (proposal.actionType == 'reassign_collection') {
      final targetColId = proposal.parameters['targetCollectionId'] as String;
      for (final rid in proposal.targetResourceIds) {
        await linkResourceToCollection(rid, targetColId);
      }
      proposal.isExecuted = true;
    }
  }

  /// Natural Language Query Engine (Offline-First Rule-Based with Tool Calling)
  Future<AiAssistantResponse> processQuery(String rawQuery) async {
    final query = rawQuery.trim();
    final lower = query.toLowerCase();

    // 1. Detection: Organization / Triage Intent
    if (lower.contains('organize') || lower.contains('move to') || lower.contains('categorize')) {
      final all = getResources();
      final untagged = all.where((r) => r.tags.isEmpty || r.notes.isEmpty).toList();

      String targetCat = 'GitHub';
      if (lower.contains('food') || lower.contains('restaurant') || lower.contains('reel')) {
        targetCat = 'Food';
      } else if (lower.contains('design') || lower.contains('ui')) {
        targetCat = 'Design';
      }

      if (untagged.isNotEmpty) {
        final ids = untagged.take(5).map((e) => e.id).toList();
        final proposal = prepareBulkOrganization(
          targetCategory: targetCat,
          resourceIds: ids,
        );

        return AiAssistantResponse(
          message: 'I reviewed your inbox and found ${ids.length} unorganized items. Here is a proposed action for your review:',
          matchingResources: untagged.take(5).toList(),
          proposal: proposal,
        );
      } else {
        return const AiAssistantResponse(
          message: 'All your resources are already cleanly organized into collections! ✨',
        );
      }
    }

    // 2. Detection: Search / Query Intent
    String cleanTerm = lower
        .replaceAll('find', '')
        .replaceAll('search', '')
        .replaceAll('show me', '')
        .replaceAll('where is', '')
        .replaceAll('my', '')
        .trim();

    if (cleanTerm.isEmpty) cleanTerm = lower;
    final results = searchResources(cleanTerm);

    if (results.isNotEmpty) {
      return AiAssistantResponse(
        message: 'Found ${results.length} saved resources matching "$cleanTerm":',
        matchingResources: results,
      );
    } else {
      return AiAssistantResponse(
        message: 'I could not find any saved resources matching "$rawQuery". Try searching for topics like "github", "food", "design", or tags like "#pdf".',
      );
    }
  }
}

